class Store:
    def __init__(self):
        self.data = {}

    def set(self, key, value):
        self.data[key] = value

    def get(self, key):
        return self.data.get(key)

    def delete(self, key):
        if key not in self.data:
            return False
        del self.data[key]
        return True

    def keys(self):
        return sorted(self.data)

    def incr(self, key):
        value = self.data.get(key, "0")
        if not value.lstrip("-").isdigit():
            raise ValueError("value is not an integer")
        n = int(value) + 1
        self.set(key, str(n))
        return n

